var game=UnityEngine.Object.FindFirstObjectByType<Cheon.Prototype.MountainPass.PassGameFlow>();var player=game.Player.GetComponent<Cheon.Prototype.MountainPass.PassPlayerMovement>();var body=player.GetComponent<CharacterController>();var report=new System.Collections.Generic.Dictionary<string,object>();
var firstData=Newtonsoft.Json.Linq.JArray.Parse(System.IO.File.ReadAllText("Assets/Temp/MountainPassRefinement~/Test_StepGeometry.json"));var first=firstData.Select(d=>new Vector3((float)d["center"][0],(float)d["center"][1]+.04f,(float)d["center"][2])).ToArray();
Vector3[] Steps(string name){var collider=GameObject.Find("MountainPassEnvironment/"+name).GetComponent<MeshCollider>();var bounds=collider.bounds;var samples=new System.Collections.Generic.List<Vector3>();for(float x=bounds.min.x;x<=bounds.max.x;x+=.38f)for(float z=bounds.min.z;z<=bounds.max.z;z+=.38f){RaycastHit hit;if(collider.Raycast(new Ray(new Vector3(x,bounds.max.y+3f,z),Vector3.down),out hit,bounds.size.y+5f)&&hit.normal.y>.98f)samples.Add(hit.point);}return samples.GroupBy(p=>System.Math.Round(p.y,2)).Where(g=>g.Count()>=3).OrderBy(g=>g.Key).Select(g=>new Vector3(g.Average(p=>p.x),g.Average(p=>p.y)+.04f,g.Average(p=>p.z))).ToArray();}
var second=Steps("Stairway_Between_Summits");var route=new System.Collections.Generic.List<Vector3>();route.AddRange(first.Skip(1));route.Add(new Vector3(15.75f,27.2f,25.1f));route.Add(new Vector3(18.8f,27.2f,22.49f));route.Add(new Vector3(20f,27.92f,21.28f));route.Add(new Vector3(21.85f,28.75f,19.45f));route.Add(game.Shrine.Position);int shrineNode=route.Count-1;
route.Add(new Vector3(21.85f,28.75f,19.45f));route.Add(new Vector3(20f,27.92f,21.28f));route.Add(new Vector3(18.8f,27.2f,22.49f));route.Add(new Vector3(15.75f,27.2f,25.1f));route.AddRange(second);var gate=game.Entrance.transform;Vector3 before=gate.position-gate.forward*2.5f;before.y=37.2f;Vector3 after=gate.position+gate.forward*2.5f;after.y=37.2f;route.Add(before);route.Add(after);
System.Collections.IEnumerator Routine(){game.BeginJourney();game.Boss.enabled=false;player.InputEnabled=false;var atmosphere=UnityEngine.Object.FindFirstObjectByType<Cheon.Prototype.MountainPass.PassStairAtmosphere>();yield return null;report["lowerBrightness"]=atmosphere.Brightness;float vertical=0,started=Time.time;int reached=0;string blocked=null;
for(int i=0;i<route.Count;i++){float nodeStart=Time.time;float budget=3f+Vector3.Distance(player.transform.position,route[i])/4f;while(Vector2.Distance(new Vector2(player.transform.position.x,player.transform.position.z),new Vector2(route[i].x,route[i].z))>.35f){if(Time.time-nodeStart>budget||Time.time-started>100){blocked="node "+i+" target="+route[i]+" position="+player.transform.position;break;}if(game.State==Cheon.Prototype.MountainPass.PassGameFlow.RunState.Cinematic)break;var direction=route[i]-player.transform.position;direction.y=0;if(body.isGrounded&&vertical<0)vertical=-2;vertical+=-24*Time.deltaTime;var displacement=Vector3.ClampMagnitude(direction,6.6f*Time.deltaTime);displacement.y=vertical*Time.deltaTime;if(direction.sqrMagnitude>.001f)player.transform.rotation=Quaternion.LookRotation(direction);player.AnimationControl.SetLocomotion(true,1f);body.Move(displacement);yield return null;}if(blocked!=null)break;reached++;
if(i==92){report["upperBrightness"]=atmosphere.Brightness;report["upperStairY"]=player.transform.position.y;}
if(i==shrineNode){report["shrineFloorY"]=player.transform.position.y;report["shrineInteractable"]=game.Shrine.CanInteract;game.PlayerHealth.TakeDamage(30);game.Shrine.Interact();yield return new WaitForSeconds(1.4f);report["prayerRestores"]=game.ReachedShrine&&game.PlayerHealth.Fraction>.99f;player.InputEnabled=false;}
}
report["reached"]=reached;report["total"]=route.Count;report["blocked"]=blocked;report["seconds"]=Time.time-started;report["crossingTriggersCinematic"]=game.State==Cheon.Prototype.MountainPass.PassGameFlow.RunState.Cinematic;report["playerFrozenInCinematic"]=!player.InputEnabled;report["nativeTimelinePlaying"]=game.Entrance.IsPresenting;var cinema=GameObject.Find("BossIntroductionCamera").GetComponent<Camera>();Vector3 cameraStart=cinema.transform.position;if(game.State==Cheon.Prototype.MountainPass.PassGameFlow.RunState.Cinematic){yield return new WaitForSeconds(2);report["timelineTime"]=game.Entrance.Director.time;report["timelineCameraMoved"]=Vector3.Distance(cameraStart,cinema.transform.position)>1f;report["cinemaCameraPosition"]=cinema.transform.position.ToString();report["cinemaActive"]=cinema.enabled&&!game.View.GetComponent<Camera>().enabled;yield return new WaitForSeconds(4.2f);report["timelineReturnsToGameplay"]=game.IsRunning&&player.InputEnabled&&game.View.enabled&&game.View.GetComponent<Camera>().enabled&&!cinema.enabled;report["bossAwakened"]=game.Boss.State.ToString();}
player.AnimationControl.SetLocomotion(false);game.Boss.enabled=true;report["completed"]=true;System.IO.File.WriteAllText("Assets/Temp/MountainPassRefinement~/Test_RouteReport.json",Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented));}
game.StartCoroutine(Routine());return new{started=true,total=route.Count,shrineNode,firstSteps=first.Length,secondSteps=second.Length};
